import csv
occ="0361d2c1-48db-57ae-b48b-913d1c1cef38"
pow="49eac0ff-63d2-57a8-90a0-fdee8aaf25a6"
o={}
p={}
for tid,ts,val in csv.reader(open(VALUES_CSV)):
    if ts.startswith("2018-01-10"):
        if tid==occ: o[ts]=val
        if tid==pow: p[ts]=val
common=set(o)&set(p)
print(len(o),len(p),len(common))
count=0
for ts in common:
    try:
        if float(p[ts])>1.0 and float(o[ts])==0.0:
            count+=1
    except: pass
print(count)
# sanity
print(list(common)[:5])
